INSERT INTO public.content_collections (key, data, updated_at) VALUES
('tours', '[{"id":"t-royal","slug":"royal-transylvania","status":"published","featured":true,"order":1,"days":7,"media":"oldTown","gallery":["oldTown","mountains","countryside"],"regions":["transylvania","carpathians","bucharest"],"styles":["heritage","private","family","romantic"],"familyFriendly":true,"privateOption":true,"seasons":["spring","summer","autumn","winter"],"title":{"en":"Royal Transylvania","ar":"ترانسيلفانيا الملكية","ro":"Transilvania regală"},"tagline":{"en":"Castles, old towns and mountain air in one graceful week","ar":"قلاع وبلدات قديمة وهواء الجبال في أسبوع أنيق واحد","ro":"Castele, orașe vechi și aer de munte într-o săptămână elegantă"},"places":{"en":"Sinaia · Brașov · Bran · Sibiu","ar":"سينايا · براشوف · بران · سيبيو","ro":"Sinaia · Brașov · Bran · Sibiu"},"overview":{"en":"A week-long concept for travellers who want Romania''s classic heart without rushing it. Royal-era architecture in the Prahova Valley, the medieval lanes of Brașov, the Bran area and the elegant squares of Sibiu are linked by mountain scenery, with free time protected throughout.","ar":"تصوّر لرحلة مدتها أسبوع لمن يرغب في اكتشاف قلب رومانيا الكلاسيكي دون عجلة. عمارة العهد الملكي في وادي براهوفا، وأزقة براشوف التاريخية، ومنطقة بران، وساحات سيبيو الأنيقة، تربط بينها مناظر الجبال مع وقت حر محفوظ طوال الرحلة.","ro":"Un concept de o săptămână pentru cei care vor să descopere inima clasică a României fără grabă. Arhitectura epocii regale din Valea Prahovei, străduțele medievale ale Brașovului, zona Bran și piețele elegante ale Sibiului sunt legate de peisaje montane, cu timp liber păstrat pe tot parcursul."},"idealFor":{"en":"Premium couples, families and private groups","ar":"الأزواج الباحثون عن تجربة مميزة والعائلات والمجموعات الخاصة","ro":"Cupluri exigente, familii și grupuri private"},"highlights":[{"en":"Optional Peleș Castle visit in Sinaia, subject to opening and tickets","ar":"زيارة اختيارية لقلعة بيليش في سينايا، حسب مواعيد الفتح وتوفر التذاكر","ro":"Vizită opțională la Castelul Peleș din Sinaia, în funcție de program și bilete"},{"en":"Brașov''s historic centre with unhurried free time","ar":"مركز براشوف التاريخي مع وقت حر دون عجلة","ro":"Centrul istoric al Brașovului, cu timp liber fără grabă"},{"en":"A comfortably paced Bran area excursion","ar":"رحلة إلى منطقة بران بإيقاع مريح","ro":"Excursie în zona Bran, într-un ritm confortabil"},{"en":"Sibiu''s heritage squares and rooftops","ar":"ساحات سيبيو التراثية وأسطحها المميزة","ro":"Piețele și acoperișurile istorice ale Sibiului"},{"en":"Mountain scenery along the way","ar":"مناظر جبلية على امتداد الطريق","ro":"Peisaje montane pe parcurs"}],"itinerary":[{"en":"Arrival in Bucharest; welcome and an unhurried first evening.","ar":"الوصول إلى بوخارست؛ استقبال وأمسية أولى هادئة.","ro":"Sosire în București; primire și o primă seară liniștită."},{"en":"Travel towards Sinaia, with an optional Peleș Castle visit subject to opening and tickets; continue to Brașov.","ar":"التوجه نحو سينايا مع زيارة اختيارية لقلعة بيليش حسب مواعيد الفتح والتذاكر، ثم متابعة الطريق إلى براشوف.","ro":"Drum spre Sinaia, cu vizită opțională la Castelul Peleș în funcție de program și bilete; continuare spre Brașov."},{"en":"Brașov historic centre and free time; optional local cultural experience.","ar":"مركز براشوف التاريخي ووقت حر؛ تجربة ثقافية محلية اختيارية.","ro":"Centrul istoric al Brașovului și timp liber; experiență culturală locală opțională."},{"en":"Bran area and castle excursion, with comfortable pacing and alternatives.","ar":"رحلة إلى منطقة بران وقلعتها بإيقاع مريح مع بدائل متاحة.","ro":"Excursie în zona Bran și la castel, într-un ritm confortabil și cu alternative."},{"en":"Scenic journey toward Sibiu, potentially via Sighișoara subject to routing and comfort review.","ar":"رحلة خلابة نحو سيبيو، وقد تمر بسيغيشوارا وفق مراجعة المسار ومستوى الراحة.","ro":"Drum pitoresc spre Sibiu, eventual prin Sighișoara, în funcție de traseu și confort."},{"en":"Sibiu heritage walk, then return toward Bucharest or an adapted overnight stop.","ar":"جولة تراثية في سيبيو ثم العودة نحو بوخارست أو مبيت في محطة مُكيَّفة.","ro":"Plimbare prin centrul istoric al Sibiului, apoi întoarcere spre București sau o înnoptare adaptată."},{"en":"Departure; transfer only if included and confirmed in the final quote.","ar":"المغادرة؛ التوصيل فقط إذا كان مشمولًا ومؤكدًا في العرض النهائي.","ro":"Plecare; transferul doar dacă este inclus și confirmat în oferta finală."}],"customize":{"en":"Lengthen to 8–9 days for a slower pace, add a private guide or swap Sibiu for more mountain time.","ar":"يمكن تمديدها إلى 8–9 أيام لإيقاع أهدأ، أو إضافة مرشد خاص، أو استبدال سيبيو بوقت أطول في الجبال.","ro":"Poate fi extins la 8–9 zile pentru un ritm mai lent, cu ghid privat sau mai mult timp la munte în locul Sibiului."},"accommodation":{"en":"Tell us your preferred comfort level — boutique, premium or family-friendly. Specific hotels are proposed only in a confirmed quote.","ar":"أخبرنا بمستوى الراحة المفضل لديك — فندق بوتيك أو فاخر أو مناسب للعائلات. تُقترح الفنادق المحددة فقط في عرض مؤكد.","ro":"Spune-ne nivelul de confort preferat — boutique, premium sau potrivit familiilor. Hotelurile concrete se propun doar într-o ofertă confirmată."},"notes":{"en":"Transfer times and the final route require operator validation; no stop is guaranteed until confirmed.","ar":"تحتاج أوقات التنقل والمسار النهائي إلى تحقق من الجهة المنظمة، ولا تُضمن أي محطة قبل تأكيدها.","ro":"Duratele transferurilor și traseul final necesită validarea operatorului; nicio oprire nu este garantată până la confirmare."},"inclusions":null,"related":["carpathian-family-escape","bucharest-and-beyond"]},{"id":"t-authentic","slug":"authentic-romania","status":"published","featured":true,"order":2,"days":9,"media":"countryside","gallery":["countryside","oldTown","mountains"],"regions":["transylvania","maramures","bucovina","bucharest"],"styles":["heritage","groups","family","nature"],"familyFriendly":true,"privateOption":true,"seasons":["spring","summer","autumn"],"title":{"en":"Authentic Romania","ar":"رومانيا الأصيلة","ro":"România autentică"},"tagline":{"en":"Countryside, craftsmanship and heritage towns","ar":"ريف وحِرف تقليدية وبلدات تراثية","ro":"Sate, meșteșuguri și orașe de patrimoniu"},"places":{"en":"Transylvania · Maramureș · Bucovina","ar":"ترانسيلفانيا · ماراموريش · بوكوفينا","ro":"Transilvania · Maramureș · Bucovina"},"overview":{"en":"A loop for culture-loving travellers that moves from Transylvania''s towns to the wooden villages of Maramureș and the green valleys of Bucovina. Three large regions in nine days means substantial driving — we will gladly propose a slower 10–11 day version.","ar":"مسار دائري لعشاق الثقافة ينتقل من بلدات ترانسيلفانيا إلى القرى الخشبية في ماراموريش والوديان الخضراء في بوكوفينا. ثلاث مناطق كبيرة في تسعة أيام تعني تنقلات طويلة بالسيارة، ويسعدنا اقتراح نسخة أهدأ من 10–11 يومًا.","ro":"Un circuit pentru iubitorii de cultură, din orașele Transilvaniei spre satele din lemn ale Maramureșului și văile verzi ale Bucovinei. Trei regiuni mari în nouă zile înseamnă mult drum — îți putem propune cu plăcere o variantă mai lentă, de 10–11 zile."},"idealFor":{"en":"Culture-loving small groups and families","ar":"المجموعات الصغيرة والعائلات المحبة للثقافة","ro":"Grupuri mici și familii pasionate de cultură"},"highlights":[{"en":"Rural landscapes of Maramureș","ar":"المناظر الريفية في ماراموريش","ro":"Peisajele rurale ale Maramureșului"},{"en":"Craft traditions, with demonstrations on request","ar":"تقاليد الحِرف مع عروض عند الطلب","ro":"Tradiții meșteșugărești, cu demonstrații la cerere"},{"en":"Bucovina''s cultural heritage, subject to access","ar":"التراث الثقافي لبوكوفينا وفق إمكانية الدخول","ro":"Patrimoniul cultural al Bucovinei, în funcție de acces"},{"en":"Transylvanian towns en route","ar":"بلدات ترانسيلفانيا على الطريق","ro":"Orașe transilvănene pe traseu"}],"itinerary":[{"en":"Arrival in Bucharest.","ar":"الوصول إلى بوخارست.","ro":"Sosire în București."},{"en":"Sinaia and Brașov.","ar":"سينايا وبراشوف.","ro":"Sinaia și Brașov."},{"en":"Transylvanian towns en route to Sibiu.","ar":"بلدات ترانسيلفانيا في الطريق إلى سيبيو.","ro":"Orașe transilvănene în drum spre Sibiu."},{"en":"Travel into Maramureș — a substantial driving day.","ar":"الانتقال إلى ماراموريش — يوم طويل من القيادة.","ro":"Drum spre Maramureș — o zi cu mult condus."},{"en":"Village landscapes and traditions.","ar":"مناظر القرى وتقاليدها.","ro":"Peisaje și tradiții de sat."},{"en":"Travel toward Bucovina.","ar":"الانتقال نحو بوكوفينا.","ro":"Drum spre Bucovina."},{"en":"Cultural and scenic discovery in Bucovina.","ar":"استكشاف ثقافي وطبيعي في بوكوفينا.","ro":"Descoperire culturală și peisagistică în Bucovina."},{"en":"Long transfer toward a suitable departure gateway; routing subject to operational review.","ar":"تنقل طويل نحو نقطة مغادرة مناسبة؛ المسار يخضع للمراجعة التشغيلية.","ro":"Transfer lung spre un punct de plecare potrivit; traseul se stabilește după analiza operațională."},{"en":"Departure.","ar":"المغادرة.","ro":"Plecare."}],"customize":{"en":"We recommend considering 10–11+ days to reduce daily driving. Private vehicle and guide language can be requested.","ar":"ننصح بالنظر في مدة 10–11 يومًا أو أكثر لتقليل ساعات القيادة اليومية. يمكن طلب مركبة خاصة ولغة المرشد المفضلة.","ro":"Recomandăm 10–11+ zile pentru a reduce condusul zilnic. Se pot solicita vehicul privat și limba ghidului."},"accommodation":{"en":"Characterful guesthouses or comfortable hotels — share your preference. Exact properties appear only in a confirmed quote.","ar":"بيوت ضيافة ذات طابع خاص أو فنادق مريحة — شاركنا تفضيلك. تظهر أماكن الإقامة المحددة فقط في عرض مؤكد.","ro":"Pensiuni cu caracter sau hoteluri confortabile — spune-ne preferința ta. Proprietățile exacte apar doar în oferta confirmată."},"notes":{"en":"Meetings with locals, access to private property or specific religious and UNESCO sites are not guaranteed without confirmation.","ar":"لا تُضمن اللقاءات مع السكان المحليين أو دخول الممتلكات الخاصة أو مواقع دينية ومواقع يونسكو محددة دون تأكيد.","ro":"Întâlnirile cu localnici, accesul la proprietăți private sau la anumite obiective religioase și UNESCO nu sunt garantate fără confirmare."},"inclusions":null,"related":["royal-transylvania"]},{"id":"t-family","slug":"carpathian-family-escape","status":"published","featured":true,"order":3,"days":6,"media":"mountains","gallery":["mountains","countryside","oldTown"],"regions":["carpathians","transylvania","bucharest"],"styles":["family","nature","private"],"familyFriendly":true,"privateOption":true,"seasons":["spring","summer","autumn","winter"],"title":{"en":"Carpathian Family Escape","ar":"رحلة عائلية إلى الكاربات","ro":"Evadare în familie în Carpați"},"tagline":{"en":"Mountain air, gentle days and room to rest","ar":"هواء الجبال وأيام هادئة ومتسع للراحة","ro":"Aer de munte, zile blânde și timp de odihnă"},"places":{"en":"Sinaia · Brașov · nearby mountains","ar":"سينايا · براشوف · الجبال المجاورة","ro":"Sinaia · Brașov · munții din apropiere"},"overview":{"en":"A relaxed, flexible concept for families: short transfers, rest time built in, and nature days chosen around your children''s ages and the weather. Private options are available on request.","ar":"تصوّر مرن وهادئ للعائلات: تنقلات قصيرة، ووقت مخصص للراحة، وأيام في الطبيعة تُختار وفق أعمار أطفالك والطقس. تتوفر خيارات خاصة عند الطلب.","ro":"Un concept relaxat și flexibil pentru familii: transferuri scurte, timp de odihnă și zile în natură alese după vârsta copiilor și vreme. Opțiunile private sunt disponibile la cerere."},"idealFor":{"en":"Families with children of different ages","ar":"العائلات مع أطفال من أعمار مختلفة","ro":"Familii cu copii de vârste diferite"},"highlights":[{"en":"Scenic stops on the way to Sinaia","ar":"توقفات خلابة في الطريق إلى سينايا","ro":"Opriri pitorești în drum spre Sinaia"},{"en":"A family nature day matched to ages and weather","ar":"يوم عائلي في الطبيعة يناسب الأعمار والطقس","ro":"O zi în natură potrivită vârstelor și vremii"},{"en":"Built-in rest and weather contingencies","ar":"وقت للراحة وخطط بديلة للطقس","ro":"Timp de odihnă și variante pentru vreme rea"},{"en":"Optional upgrades on request","ar":"ترقيات اختيارية عند الطلب","ro":"Upgrade-uri opționale, la cerere"}],"itinerary":[{"en":"Arrival in Bucharest.","ar":"الوصول إلى بوخارست.","ro":"Sosire în București."},{"en":"Transfer to Sinaia with scenic stops.","ar":"الانتقال إلى سينايا مع توقفات خلابة.","ro":"Transfer la Sinaia, cu opriri pitorești."},{"en":"Gentle local experiences.","ar":"تجارب محلية هادئة.","ro":"Experiențe locale liniștite."},{"en":"A family-friendly nature day chosen for children''s ages and weather.","ar":"يوم في الطبيعة مناسب للعائلة يُختار وفق أعمار الأطفال والطقس.","ro":"O zi în natură potrivită familiei, aleasă după vârsta copiilor și vreme."},{"en":"Flexible rest, then return toward Bucharest.","ar":"راحة مرنة ثم العودة نحو بوخارست.","ro":"Odihnă flexibilă, apoi întoarcere spre București."},{"en":"Departure.","ar":"المغادرة.","ro":"Plecare."}],"customize":{"en":"Adjust days, add a city day in Brașov, or request a private driver. Not every activity suits every child — we tailor together.","ar":"عدّل عدد الأيام، أو أضف يومًا في براشوف، أو اطلب سائقًا خاصًا. ليست كل الأنشطة مناسبة لكل طفل، لذا نخطط معًا.","ro":"Ajustează numărul de zile, adaugă o zi la Brașov sau solicită șofer privat. Nu orice activitate se potrivește fiecărui copil — adaptăm împreună."},"accommodation":{"en":"Family rooms or connecting rooms can be requested, subject to availability at quotation.","ar":"يمكن طلب غرف عائلية أو غرف متصلة، حسب التوفر عند إعداد العرض.","ro":"Se pot solicita camere de familie sau comunicante, în funcție de disponibilitate la ofertare."},"notes":{"en":"Activities depend on weather, season and children''s ages; suitability is informative, not a safety guarantee.","ar":"تعتمد الأنشطة على الطقس والموسم وأعمار الأطفال، والملاءمة معلومة استرشادية وليست ضمانًا للسلامة.","ro":"Activitățile depind de vreme, sezon și vârsta copiilor; potrivirea este informativă, nu o garanție de siguranță."},"inclusions":null,"related":["royal-transylvania","bucharest-and-beyond"]},{"id":"t-bucharest","slug":"bucharest-and-beyond","status":"published","featured":false,"order":4,"days":5,"media":"oldTown","gallery":["oldTown","mountains"],"regions":["bucharest","carpathians"],"styles":["romantic","private","heritage","family"],"familyFriendly":true,"privateOption":true,"seasons":["spring","summer","autumn","winter"],"title":{"en":"Bucharest & Beyond","ar":"بوخارست وما بعدها","ro":"București și împrejurimi"},"tagline":{"en":"A short, easy first taste of Romania","ar":"تجربة أولى قصيرة وسهلة لرومانيا","ro":"O primă întâlnire scurtă și ușoară cu România"},"places":{"en":"Bucharest · optional Sinaia excursion","ar":"بوخارست · رحلة اختيارية إلى سينايا","ro":"București · excursie opțională la Sinaia"},"overview":{"en":"A demonstration proposal for first visits, couples and short family breaks — the capital''s architecture and parks with an optional mountain excursion and a free or wellness day.","ar":"مقترح توضيحي للزيارات الأولى والأزواج والعطلات العائلية القصيرة — عمارة العاصمة وحدائقها مع رحلة جبلية اختيارية ويوم حر أو للاسترخاء.","ro":"O propunere demonstrativă pentru prime vizite, cupluri și vacanțe scurte în familie — arhitectura și parcurile capitalei, cu o excursie opțională la munte și o zi liberă sau de wellness."},"idealFor":{"en":"First-time visitors, couples, short family breaks","ar":"الزائرون لأول مرة والأزواج والعطلات العائلية القصيرة","ro":"Vizitatori la prima experiență, cupluri, vacanțe scurte în familie"},"highlights":[{"en":"Curated architecture and history in Bucharest","ar":"جولة منتقاة في عمارة بوخارست وتاريخها","ro":"Arhitectură și istorie în București"},{"en":"Optional Sinaia/Peleș excursion, subject to opening","ar":"رحلة اختيارية إلى سينايا/بيليش حسب مواعيد الفتح","ro":"Excursie opțională Sinaia/Peleș, în funcție de program"},{"en":"Free or wellness day, subject to venue rules","ar":"يوم حر أو للاسترخاء وفق قواعد المكان","ro":"Zi liberă sau de wellness, conform regulilor locației"}],"itinerary":[{"en":"Arrival and rest.","ar":"الوصول والراحة.","ro":"Sosire și odihnă."},{"en":"Curated architecture and history in Bucharest.","ar":"جولة منتقاة في عمارة بوخارست وتاريخها.","ro":"Arhitectură și istorie în București."},{"en":"Optional Sinaia/Peleș excursion, subject to opening and transport duration.","ar":"رحلة اختيارية إلى سينايا/بيليش حسب مواعيد الفتح ومدة التنقل.","ro":"Excursie opțională Sinaia/Peleș, în funcție de program și durata drumului."},{"en":"Free time or a requested wellness, spa or cultural day, subject to supplier confirmation.","ar":"وقت حر أو يوم استرخاء أو سبا أو ثقافي عند الطلب، بشرط تأكيد المزود.","ro":"Timp liber sau o zi de wellness, spa ori culturală, la cerere și sub rezerva confirmării furnizorului."},{"en":"Departure.","ar":"المغادرة.","ro":"Plecare."}],"customize":{"en":"Combine with the Carpathians for a longer stay, or keep it entirely in the city.","ar":"يمكن دمجها مع الكاربات لإقامة أطول، أو إبقاؤها بالكامل داخل المدينة.","ro":"Poate fi combinat cu Carpații pentru un sejur mai lung sau păstrat integral în oraș."},"accommodation":{"en":"Central city hotels at your preferred comfort level; properties proposed only in a confirmed quote.","ar":"فنادق في وسط المدينة بمستوى الراحة الذي تفضله؛ تُقترح أماكن الإقامة فقط في عرض مؤكد.","ro":"Hoteluri centrale la nivelul de confort dorit; proprietățile se propun doar într-o ofertă confirmată."},"notes":{"en":"This is a demonstration proposal, not a contracted product.","ar":"هذا مقترح توضيحي وليس منتجًا متعاقدًا عليه.","ro":"Aceasta este o propunere demonstrativă, nu un produs contractat."},"inclusions":null,"related":["royal-transylvania","carpathian-family-escape"]}]'::jsonb, now()),
('destinations', '[{"slug":"transylvania","media":"oldTown","name":{"en":"Transylvania","ar":"ترانسيلفانيا","ro":"Transilvania"},"teaser":{"en":"Castles, Saxon towns and forested hills","ar":"قلاع وبلدات سكسونية وتلال مكسوة بالغابات","ro":"Castele, orașe săsești și dealuri împădurite"},"intro":{"en":"Encircled by the Carpathian arc, Transylvania is Romania''s historic heartland: medieval town centres such as Brașov, Sibiu and Sighișoara, fortified churches, and castles set against wooded slopes.","ar":"تحيط بها قوس جبال الكاربات، وتُعد ترانسيلفانيا القلب التاريخي لرومانيا: مراكز مدن من العصور الوسطى مثل براشوف وسيبيو وسيغيشوارا، وكنائس محصّنة، وقلاع على سفوح الغابات.","ro":"Înconjurată de arcul Carpaților, Transilvania este inima istorică a României: centre medievale precum Brașov, Sibiu și Sighișoara, biserici fortificate și castele pe fundalul pantelor împădurite."},"why":[{"en":"Walkable old towns with squares and cafés","ar":"بلدات قديمة يسهل التجول فيها بساحاتها ومقاهيها","ro":"Orașe vechi ușor de parcurs pe jos, cu piețe și cafenele"},{"en":"Castle visits that can be combined in one region","ar":"زيارات للقلاع يمكن جمعها في منطقة واحدة","ro":"Vizite la castele ce pot fi combinate într-o singură regiune"},{"en":"Mountain scenery within short distances","ar":"مناظر جبلية على مسافات قصيرة","ro":"Peisaje montane la distanțe scurte"}],"experiences":[{"en":"Heritage walks","ar":"جولات تراثية","ro":"Plimbări prin patrimoniu"},{"en":"Family-paced castle days","ar":"أيام لزيارة القلاع بإيقاع عائلي","ro":"Zile la castele, în ritm de familie"},{"en":"Local cultural experiences on request","ar":"تجارب ثقافية محلية عند الطلب","ro":"Experiențe culturale locale, la cerere"}],"seasons":{"en":"Late spring to early autumn is generally the most comfortable; winters are cold and atmospheric. Opening hours of castles and museums vary and are checked at quotation.","ar":"تكون الفترة من أواخر الربيع حتى أوائل الخريف الأكثر راحة عادةً، والشتاء بارد وذو طابع خاص. تختلف مواعيد فتح القلاع والمتاحف ويتم التحقق منها عند إعداد العرض.","ro":"De la sfârșitul primăverii până la începutul toamnei este, de regulă, perioada cea mai confortabilă; iernile sunt reci și pline de atmosferă. Programul castelelor și muzeelor variază și se verifică la ofertare."}},{"slug":"bucharest","media":"oldTown","name":{"en":"Bucharest","ar":"بوخارست","ro":"București"},"teaser":{"en":"Boulevards, parks and a lively capital","ar":"شوارع واسعة وحدائق وعاصمة نابضة","ro":"Bulevarde, parcuri și o capitală vie"},"intro":{"en":"Romania''s capital mixes Belle Époque façades, grand boulevards, large parks and a lively café culture. It is the usual international arrival point and a natural first or last stop.","ar":"تمزج عاصمة رومانيا بين واجهات الحقبة الجميلة والشوارع الكبرى والحدائق الواسعة وثقافة المقاهي النابضة. وهي نقطة الوصول الدولية المعتادة، والمحطة الأولى أو الأخيرة بطبيعة الحال.","ro":"Capitala României îmbină fațade Belle Époque, bulevarde largi, parcuri mari și o cultură vie a cafenelelor. Este punctul obișnuit de sosire internațională și o primă sau ultimă oprire firească."},"why":[{"en":"Easy start after an international flight","ar":"بداية سهلة بعد رحلة جوية دولية","ro":"Început ușor după un zbor internațional"},{"en":"Architecture, museums and green spaces","ar":"عمارة ومتاحف ومساحات خضراء","ro":"Arhitectură, muzee și spații verzi"},{"en":"A base for selected day excursions","ar":"قاعدة لرحلات يومية مختارة","ro":"Bază pentru excursii de o zi selectate"}],"experiences":[{"en":"Curated architecture and history walks","ar":"جولات منتقاة في العمارة والتاريخ","ro":"Plimbări dedicate arhitecturii și istoriei"},{"en":"Wellness or spa day on request","ar":"يوم استرخاء أو سبا عند الطلب","ro":"Zi de wellness sau spa, la cerere"},{"en":"Family time in the city''s parks","ar":"وقت عائلي في حدائق المدينة","ro":"Timp în familie în parcurile orașului"}],"seasons":{"en":"Summers can be hot; spring and autumn are pleasant for walking. City traffic affects excursion timing.","ar":"قد يكون الصيف حارًا، بينما يُعد الربيع والخريف مناسبين للتجول سيرًا. تؤثر حركة المرور على توقيت الرحلات اليومية.","ro":"Verile pot fi calde; primăvara și toamna sunt plăcute pentru plimbări. Traficul influențează durata excursiilor."}},{"slug":"carpathians","media":"mountains","name":{"en":"Carpathian Mountains","ar":"جبال الكاربات","ro":"Munții Carpați"},"teaser":{"en":"Alpine air, forests and scenic roads","ar":"هواء جبلي وغابات وطرق خلابة","ro":"Aer alpin, păduri și drumuri panoramice"},"intro":{"en":"The Carpathians curve through the centre of Romania, from the Prahova Valley resorts around Sinaia to high passes. Summer brings cool air; winter brings snow and mountain resorts.","ar":"تنحني جبال الكاربات عبر وسط رومانيا، من منتجعات وادي براهوفا حول سينايا إلى الممرات المرتفعة. يحمل الصيف هواءً منعشًا، ويأتي الشتاء بالثلوج والمنتجعات الجبلية.","ro":"Carpații traversează centrul României, de la stațiunile din Valea Prahovei din jurul Sinaiei până la pasurile înalte. Vara aduce aer răcoros; iarna aduce zăpadă și stațiuni montane."},"why":[{"en":"A welcome contrast to Gulf summer heat","ar":"تباين مرحّب به مع حرارة صيف الخليج","ro":"Un contrast binevenit cu căldura verii din Golf"},{"en":"Gentle walks and viewpoints for all ages","ar":"نزهات خفيفة ونقاط مشاهدة لجميع الأعمار","ro":"Plimbări ușoare și belvedere pentru toate vârstele"},{"en":"Scenic drives — some seasonal","ar":"طرق خلابة — بعضها موسمي","ro":"Drumuri panoramice — unele sezoniere"}],"experiences":[{"en":"Nature days adapted to weather","ar":"أيام في الطبيعة تتكيف مع الطقس","ro":"Zile în natură adaptate vremii"},{"en":"Cable-car viewpoints where operating","ar":"نقاط مشاهدة بالتلفريك حيث يعمل","ro":"Belvedere cu telecabina, acolo unde funcționează"},{"en":"Winter snow experiences","ar":"تجارب الثلوج الشتوية","ro":"Experiențe de iarnă pe zăpadă"}],"seasons":{"en":"The Transfăgărășan high road is typically open only part of the year and can close for weather; it is never guaranteed in an itinerary. Mountain weather changes quickly.","ar":"يُفتح طريق ترانسفاغاراشان المرتفع عادةً خلال جزء من السنة فقط، وقد يُغلق بسبب الطقس، ولا يُضمن إدراجه في أي برنامج. يتغير الطقس في الجبال بسرعة.","ro":"Transfăgărășanul este, de regulă, deschis doar o parte din an și se poate închide din cauza vremii; nu este niciodată garantat într-un itinerariu. Vremea la munte se schimbă rapid."}},{"slug":"maramures","media":"countryside","name":{"en":"Maramureș","ar":"ماراموريش","ro":"Maramureș"},"teaser":{"en":"Wooden villages and living traditions","ar":"قرى خشبية وتقاليد حيّة","ro":"Sate din lemn și tradiții vii"},"intro":{"en":"In Romania''s far north, Maramureș is known for carved wooden gates, tall wooden churches, rolling hay meadows and a rural rhythm that feels unhurried.","ar":"في أقصى شمال رومانيا، تشتهر ماراموريش بالبوابات الخشبية المنحوتة والكنائس الخشبية الشاهقة ومروج القش المتموجة وإيقاع ريفي هادئ.","ro":"În nordul îndepărtat al României, Maramureșul este cunoscut pentru porțile sculptate, bisericile înalte din lemn, fânețele ondulate și un ritm rural fără grabă."},"why":[{"en":"Craftsmanship and rural landscapes","ar":"حِرف تقليدية ومناظر ريفية","ro":"Meșteșuguri și peisaje rurale"},{"en":"Quiet guesthouse-style stays","ar":"إقامة هادئة على طراز بيوت الضيافة","ro":"Cazări liniștite, în stil pensiune"},{"en":"A slower, authentic travel mood","ar":"أجواء سفر أبطأ وأكثر أصالة","ro":"O atmosferă de călătorie mai lentă, autentică"}],"experiences":[{"en":"Village walks","ar":"نزهات في القرى","ro":"Plimbări prin sate"},{"en":"Craft demonstrations on request","ar":"عروض للحِرف عند الطلب","ro":"Demonstrații meșteșugărești, la cerere"},{"en":"Countryside photography","ar":"تصوير الريف","ro":"Fotografie în peisaj rural"}],"seasons":{"en":"Late spring to autumn suits most travellers. Distances are long and roads rural, so allow extra travel time.","ar":"تناسب الفترة من أواخر الربيع حتى الخريف معظم المسافرين. المسافات طويلة والطرق ريفية، لذا يلزم وقت إضافي للتنقل.","ro":"Sfârșitul primăverii până toamna se potrivește majorității călătorilor. Distanțele sunt mari și drumurile rurale, deci e nevoie de timp suplimentar."}},{"slug":"bucovina","media":"countryside","name":{"en":"Bucovina","ar":"بوكوفينا","ro":"Bucovina"},"teaser":{"en":"Painted heritage and green valleys","ar":"تراث ملوّن ووديان خضراء","ro":"Patrimoniu pictat și văi verzi"},"intro":{"en":"Bucovina, in the north-east, is renowned for its painted monasteries, green valleys and traditional crafts such as decorated eggs and pottery.","ar":"تشتهر بوكوفينا في الشمال الشرقي بأديرتها المزخرفة بالرسوم ووديانها الخضراء وحِرفها التقليدية مثل البيض المزخرف والفخار.","ro":"Bucovina, în nord-est, este renumită pentru mănăstirile pictate, văile verzi și meșteșugurile tradiționale precum ouăle încondeiate și ceramica."},"why":[{"en":"Distinctive cultural heritage","ar":"تراث ثقافي مميز","ro":"Patrimoniu cultural distinctiv"},{"en":"Pastoral scenery","ar":"مناظر ريفية رعوية","ro":"Peisaje pastorale"},{"en":"Pairs naturally with Maramureș","ar":"تُدمج بشكل طبيعي مع ماراموريش","ro":"Se combină firesc cu Maramureșul"}],"experiences":[{"en":"Heritage visits subject to access rules","ar":"زيارات تراثية وفق قواعد الدخول","ro":"Vizite de patrimoniu, conform regulilor de acces"},{"en":"Craft workshops on request","ar":"ورش حِرفية عند الطلب","ro":"Ateliere meșteșugărești, la cerere"},{"en":"Scenic drives","ar":"رحلات بالسيارة عبر مناظر خلابة","ro":"Drumuri pitorești"}],"seasons":{"en":"Best from late spring to early autumn. Specific sites, opening times and visitor rules are confirmed at quotation.","ar":"الأفضل من أواخر الربيع حتى أوائل الخريف. تُؤكَّد المواقع ومواعيد الفتح وقواعد الزيارة عند إعداد العرض.","ro":"Ideal de la sfârșitul primăverii până la începutul toamnei. Obiectivele, programul și regulile de vizitare se confirmă la ofertare."}},{"slug":"danube-delta","media":"delta","name":{"en":"Danube Delta","ar":"دلتا الدانوب","ro":"Delta Dunării"},"teaser":{"en":"Waterways, reeds and birdlife","ar":"ممرات مائية وقصب وطيور","ro":"Canale, stuf și păsări"},"intro":{"en":"Where the Danube meets the Black Sea, the Delta is a vast network of channels, lakes and reed beds, protected for its wildlife and loved for its stillness.","ar":"حيث يلتقي الدانوب بالبحر الأسود، تمتد الدلتا كشبكة واسعة من القنوات والبحيرات وأحواض القصب، محمية لحياتها البرية ومحبوبة لسكينتها.","ro":"Acolo unde Dunărea întâlnește Marea Neagră, Delta este o rețea vastă de canale, lacuri și stufărișuri, protejată pentru fauna sa și iubită pentru liniștea ei."},"why":[{"en":"Rare wetland landscapes","ar":"مناظر أراضٍ رطبة نادرة","ro":"Peisaje rare de zone umede"},{"en":"Birdwatching in suitable seasons","ar":"مراقبة الطيور في المواسم المناسبة","ro":"Observarea păsărilor în sezoanele potrivite"},{"en":"A peaceful nature extension","ar":"امتداد هادئ في الطبيعة","ro":"O prelungire liniștită în natură"}],"experiences":[{"en":"Boat outings where operating","ar":"نزهات بالقارب حيث تتوفر","ro":"Ieșiri cu barca, acolo unde funcționează"},{"en":"Nature observation","ar":"مراقبة الطبيعة","ro":"Observarea naturii"},{"en":"Slow days by the water","ar":"أيام هادئة بجانب الماء","ro":"Zile lente lângă apă"}],"seasons":{"en":"Not every activity runs in every season. Boat services, birdlife and access depend on the time of year and conditions; mosquitoes are common in summer.","ar":"لا تتوفر جميع الأنشطة في كل المواسم. تعتمد خدمات القوارب والطيور وإمكانية الوصول على وقت السنة والظروف، والبعوض شائع في الصيف.","ro":"Nu toate activitățile sunt disponibile în orice sezon. Serviciile de bărci, păsările și accesul depind de perioada anului și de condiții; vara țânțarii sunt frecvenți."}}]'::jsonb, now()),
('styles', '[{"id":"family","media":"mountains","title":{"en":"Family Adventures","ar":"مغامرات عائلية","ro":"Aventuri în familie"},"intro":{"en":"Unhurried days, rest built in, and activities chosen around your children''s ages. Suitability is informative, never a safety guarantee.","ar":"أيام هادئة الإيقاع مع وقت للراحة، وأنشطة تُختار وفق أعمار أطفالك. الملاءمة معلومة استرشادية وليست ضمانًا للسلامة.","ro":"Zile fără grabă, timp de odihnă și activități alese după vârsta copiilor. Potrivirea este informativă, nu o garanție de siguranță."}},{"id":"private","media":"oldTown","title":{"en":"Private & Premium","ar":"خاصة ومميزة","ro":"Privat și premium"},"intro":{"en":"Private transfers, refined stays and personal pacing can be requested, subject to supplier confirmation.","ar":"يمكن طلب تنقلات خاصة وإقامة راقية وإيقاع شخصي، مع خضوعها لتأكيد المزودين.","ro":"Transferuri private, cazări rafinate și un ritm personal pot fi solicitate, sub rezerva confirmării furnizorilor."}},{"id":"nature","media":"mountains","title":{"en":"Mountains & Nature","ar":"الجبال والطبيعة","ro":"Munți și natură"},"intro":{"en":"Carpathian forests, cool summer air and wide valleys — with routes adapted to weather and season.","ar":"غابات الكاربات وهواء الصيف المنعش والوديان الفسيحة، مع مسارات تتكيّف مع الطقس والموسم.","ro":"Păduri carpatine, aer răcoros de vară și văi largi — cu trasee adaptate vremii și sezonului."}},{"id":"heritage","media":"oldTown","title":{"en":"History & Heritage","ar":"التاريخ والتراث","ro":"Istorie și patrimoniu"},"intro":{"en":"Castles, fortified towns and painted traditions, explored at a pace that leaves room to linger.","ar":"قلاع وبلدات محصّنة وتقاليد عريقة، تُستكشف بإيقاع يترك مجالًا للتأمل.","ro":"Castele, cetăți și tradiții, descoperite într-un ritm care lasă loc pentru răgaz."}},{"id":"romantic","media":"countryside","title":{"en":"Romantic Escapes","ar":"رحلات رومانسية","ro":"Escapade romantice"},"intro":{"en":"Quiet mountain mornings and old-town evenings for couples who prefer calm over crowds.","ar":"صباحات جبلية هادئة وأمسيات في البلدات القديمة للأزواج الذين يفضّلون السكينة على الازدحام.","ro":"Dimineți liniștite la munte și seri în orașe vechi, pentru cuplurile care preferă liniștea."}},{"id":"groups","media":"countryside","title":{"en":"Custom Groups","ar":"مجموعات مخصصة","ro":"Grupuri personalizate"},"intro":{"en":"Friends, extended families or small corporate groups — including pilot groups of around 10–12 travellers.","ar":"أصدقاء أو عائلات ممتدة أو مجموعات عمل صغيرة، بما في ذلك مجموعات تجريبية من نحو 10 إلى 12 مسافرًا.","ro":"Prieteni, familii extinse sau grupuri mici de companie — inclusiv grupuri pilot de aproximativ 10–12 persoane."}}]'::jsonb, now()),
('faq', '[{"q":{"en":"Is submitting an inquiry a booking?","ar":"هل يُعد إرسال الاستفسار حجزًا؟","ro":"Trimiterea unei solicitări înseamnă rezervare?"},"a":{"en":"No. An inquiry is non-binding. We review your ideas and prepare a personalised proposed itinerary and quotation. Nothing is booked until you accept a written offer from an authorised travel team.","ar":"لا. الاستفسار غير مُلزِم. نراجع أفكارك ونعدّ برنامجًا مقترحًا وعرض سعر مخصصًا. لا يتم حجز أي شيء قبل قبولك لعرض مكتوب من فريق سفر مُخوَّل.","ro":"Nu. Solicitarea nu este obligatorie. Analizăm ideile tale și pregătim un itinerariu propus și o ofertă personalizată. Nimic nu se rezervă până nu accepți o ofertă scrisă de la o echipă de turism autorizată."}},{"q":{"en":"Can we travel privately or as a group?","ar":"هل يمكننا السفر بشكل خاص أو ضمن مجموعة؟","ro":"Putem călători privat sau în grup?"},"a":{"en":"Both can be requested: private journeys for families or couples, and small custom groups — including groups of around 10–12 travellers. Arrangements are subject to supplier confirmation.","ar":"يمكن طلب الخيارين: رحلات خاصة للعائلات أو الأزواج، ومجموعات صغيرة مخصصة بما فيها مجموعات من نحو 10–12 مسافرًا، مع خضوع الترتيبات لتأكيد المزودين.","ro":"Ambele pot fi solicitate: călătorii private pentru familii sau cupluri și grupuri mici personalizate — inclusiv de aproximativ 10–12 persoane. Aranjamentele depind de confirmarea furnizorilor."}},{"q":{"en":"Can the itinerary be customised?","ar":"هل يمكن تخصيص البرنامج؟","ro":"Itinerariul poate fi personalizat?"},"a":{"en":"Yes. Every journey shown is an illustrative concept. Duration, pacing, regions and interests can all be adjusted in your proposal.","ar":"نعم. كل رحلة معروضة هي تصوّر توضيحي، ويمكن تعديل المدة والإيقاع والمناطق والاهتمامات في المقترح الخاص بك.","ro":"Da. Fiecare circuit prezentat este un concept ilustrativ. Durata, ritmul, regiunile și interesele pot fi ajustate în propunerea ta."}},{"q":{"en":"Can you accommodate family needs and dietary requests?","ar":"هل يمكنكم مراعاة احتياجات العائلة والطلبات الغذائية؟","ro":"Puteți ține cont de nevoile familiei și de cerințele alimentare?"},"a":{"en":"You can share family needs and dietary preferences, including halal requests, in your inquiry. We will look for suitable options, but nothing is promised until confirmed in writing.","ar":"يمكنك مشاركة احتياجات العائلة والتفضيلات الغذائية، بما في ذلك طلبات الطعام الحلال، في استفسارك. سنبحث عن خيارات مناسبة، لكن لا يُلتزم بأي شيء قبل تأكيده كتابيًا.","ro":"Poți menționa nevoile familiei și preferințele alimentare, inclusiv cereri halal, în solicitare. Vom căuta opțiuni potrivite, dar nimic nu este promis până la confirmarea scrisă."}},{"q":{"en":"What accommodation standard can we expect?","ar":"ما مستوى الإقامة الذي يمكن توقعه؟","ro":"Ce standard de cazare putem aștepta?"},"a":{"en":"You choose a preferred comfort level. Specific hotels or guesthouses are proposed only in a confirmed quotation.","ar":"تختار مستوى الراحة المفضل لديك، وتُقترح الفنادق أو بيوت الضيافة المحددة فقط في عرض سعر مؤكد.","ro":"Tu alegi nivelul de confort dorit. Hotelurile sau pensiunile concrete se propun doar într-o ofertă confirmată."}},{"q":{"en":"Are guides available in Arabic?","ar":"هل يتوفر مرشدون يتحدثون العربية؟","ro":"Există ghizi vorbitori de arabă?"},"a":{"en":"You can request a guide language. Availability of specific languages, including Arabic, cannot be promised before confirmation.","ar":"يمكنك طلب لغة المرشد، ولا يمكن ضمان توفر لغات معينة، بما فيها العربية، قبل التأكيد.","ro":"Poți solicita limba ghidului. Disponibilitatea anumitor limbi, inclusiv araba, nu poate fi promisă înainte de confirmare."}},{"q":{"en":"Do you arrange flights?","ar":"هل ترتبون رحلات الطيران؟","ro":"Organizați și zborurile?"},"a":{"en":"Let us know if flight assistance would help. Any flight arrangements would be handled only through appropriately qualified suppliers.","ar":"أخبرنا إذا كانت المساعدة في حجز الطيران مفيدة لك. أي ترتيبات للطيران ستتم فقط عبر مزودين مؤهلين بشكل مناسب.","ro":"Spune-ne dacă ai nevoie de ajutor cu zborurile. Orice aranjament de zbor s-ar face doar prin furnizori calificați corespunzător."}},{"q":{"en":"Do we need a visa?","ar":"هل نحتاج إلى تأشيرة؟","ro":"Avem nevoie de viză?"},"a":{"en":"It depends on your passport nationality, residence status, travel document, itinerary and dates. Visa-free travel for Kuwait and other GCC nationals is not yet in effect. Please check our travel information page and official sources.","ar":"يعتمد ذلك على جنسية جواز السفر ووضع الإقامة ووثيقة السفر وخط السير والتواريخ. السفر دون تأشيرة لمواطني الكويت ودول الخليج الأخرى غير ساري المفعول بعد. يُرجى مراجعة صفحة معلومات السفر والمصادر الرسمية.","ro":"Depinde de cetățenia pașaportului, statutul de rezidență, documentul de călătorie, itinerariu și date. Călătoria fără viză pentru cetățenii Kuweitului și ai altor state din Golf nu este încă în vigoare. Consultă pagina de informații de călătorie și sursele oficiale."}},{"q":{"en":"When is payment or a deposit required?","ar":"متى يُطلب الدفع أو العربون؟","ro":"Când se cere plata sau avansul?"},"a":{"en":"No payment is taken on this website. Deposits and payments would only apply after commercial authorisation and a confirmed written offer.","ar":"لا يتم تحصيل أي مبالغ عبر هذا الموقع. تُطبَّق العربونات والمدفوعات فقط بعد الحصول على التفويض التجاري وعرض مكتوب مؤكد.","ro":"Pe acest site nu se efectuează plăți. Avansul și plățile s-ar aplica doar după autorizarea comercială și o ofertă scrisă confirmată."}},{"q":{"en":"What are the cancellation terms?","ar":"ما شروط الإلغاء؟","ro":"Care sunt condițiile de anulare?"},"a":{"en":"Cancellation terms will be set out only in a confirmed written offer.","ar":"تُحدَّد شروط الإلغاء فقط في العرض المكتوب المؤكد.","ro":"Condițiile de anulare vor fi precizate doar într-o ofertă scrisă confirmată."}}]'::jsonb, now()),
('site', '{"name":"Discover Romania Kuwait","tagline":{"en":"Romania, personally planned","ar":"رومانيا، برحلة تُخطَّط لك شخصيًا","ro":"România, planificată personal"},"email":null,"whatsappDigits":"96556642402","socials":[],"businessRegistration":null}'::jsonb, now()),
('entry', '{"lastReviewed":"2026-10-29","links":[{"label":"European Commission — Visa policy","url":"https://home-affairs.ec.europa.eu/policies/schengen-borders-and-visa/visa-policy_en"},{"label":"Romanian Ministry of Foreign Affairs — Consular information","url":"https://www.mae.ro/en"},{"label":"Re-open EU / Your Europe — Travel documents","url":"https://europa.eu/youreurope/citizens/travel/entry-exit/index_en.htm"}],"body":{"en":"Entry requirements for Romania depend on your passport nationality, residence status, travel document, itinerary and travel dates. On 19 October 2026 the Council of the EU adopted conclusions to launch visa-waiver processes for Kuwait, Saudi Arabia, Qatar, Bahrain and Oman. This is the start of a process: visa-free travel is not yet in effect and no effective date has been confirmed. UAE nationals are subject to a different existing arrangement. Please always check current official EU, Romanian or consular sources before planning.","ar":"تعتمد متطلبات الدخول إلى رومانيا على جنسية جواز السفر، ووضع الإقامة، ووثيقة السفر، وخط سير الرحلة، وتواريخ السفر. في 19 أكتوبر 2026 اعتمد مجلس الاتحاد الأوروبي استنتاجات لإطلاق إجراءات الإعفاء من التأشيرة لكلٍّ من الكويت والسعودية وقطر والبحرين وعُمان. هذه بداية مسار فقط: السفر دون تأشيرة غير ساري المفعول بعد، ولم يُعلن أي تاريخ لبدء التطبيق. ويخضع مواطنو الإمارات لترتيب مختلف قائم. يُرجى دائمًا مراجعة المصادر الرسمية الحالية للاتحاد الأوروبي أو رومانيا أو الجهات القنصلية قبل التخطيط.","ro":"Condițiile de intrare în România depind de cetățenia pașaportului, statutul de rezidență, documentul de călătorie, itinerariu și datele călătoriei. La 19 octombrie 2026, Consiliul UE a adoptat concluzii pentru lansarea procedurilor de exceptare de la viză pentru Kuweit, Arabia Saudită, Qatar, Bahrain și Oman. Este doar începutul unui proces: călătoria fără viză nu este încă în vigoare și nu a fost confirmată o dată de aplicare. Cetățenii Emiratelor Arabe Unite au un regim diferit, deja existent. Verifică întotdeauna sursele oficiale actuale ale UE, ale României sau consulare înainte de planificare."}}'::jsonb, now());
